ault(false) // Whether dilation has been completed\n  dilationCompletedAt DateTime? // When dilation was completed\n  createdAt           DateTime  @default(now())\n  updatedAt           DateTime  @updatedAt\n}\n\nmodel Message {\n  id        String   @id @default(uuid())\n  text      String\n  sender    String // \"doctor\" or \"secretary\"\n  timestamp DateTime @default(now())\n  isRead    Boolean  @default(false)\n  sentBy    User?    @relation(\"SentMessages\", fields: [sentById], references: [id])\n  sentById  String?\n  createdAt DateTime @default(now())\n}\n\nmodel TodoItem {\n  id          String    @id @default(uuid())\n  text        String // Single line of text\n  isCompleted Boolean   @default(false)\n  completedAt DateTime? // Time when task was completed\n  date        DateTime  @default(now()) // Date for grouping todos by day\n  createdBy   User      @relation(\"CreatedTodos\", fields: [createdById], references: [id])\n  createdById String\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n}\n\nmodel Agenda {\n  id               Int      @id @default(autoincrement())\n  date             DateTime\n  timeSlot         String // e.g., \"08:00-09:00\"\n  isAvailable      Boolean  @default(true)\n  patientId        Int?\n  patientName      String?\n  consultationType String?\n  notes            String?\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@map(\"agenda\")\n}\n\nmodel Tarif {\n  id          Int      @id @default(autoincrement())\n  name        String\n  description String?\n  price       Float\n  category    String // \"general\", \"laser\", \"surgery\", \"injection\", \"other\"\n  isActive    Boolean  @default(true)\n  duration    Int? // duration in minutes\n  code        String? // internal code\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"tarifs\")\n}\n",
